    const grad=g.createLinearGradient(x,0,x+ridgeW,0);
    grad.addColorStop(0,'rgba(0,0,0,.32)');
    grad.addColorStop(.45,'rgba(255,255,255,.18)');
    grad.addColorStop(.55,'rgba(255,255,255,.18)');
    grad.addColorStop(1,'rgba(0,0,0,.32)');
