  {suffix:'normal',slot:'Normal',isColor:false},
  {suffix:'roughness',slot:'Roughness',isColor:false},
  {suffix:'metalness',slot:'Metalness',isColor:false},
  {suffix:'ao',slot:'Ao',isColor:false}
