  for(const z of [zp(-14),zp(-5),zp(4),zp(12)]){
    addWindow(-hw+.012, winY, z, winW, winH, '+x'); // left wall
    addWindow( hw-.012, winY, z, winW, winH, '-x'); // right wall
  }
