  _aaWeaponDetail(SPP_MESHES,false,.040,.003,.055,scratchM,0,.040,-.018,0,0,0);
  _aaWeaponDetail(SPP_MESHES,false,.030,.004,.006,darkInsetM,0,.062,-.210,0,0,0);
