  if(a.type==='scope')return Math.round(((1-m('spreadMul'))+(1-m('adsSpreadMul'))+(m('adsSpeedMul')-1))*100);
  if(a.type==='mag')return Math.round(((m('magMul')-1)*55)+((1-m('reloadMul'))*65)+((m('dmgMul')-1)*95));
