  const f=$e('dmg-flash');f.style.background='rgba(80,220,120,.30)';f.style.opacity='.9';
  setTimeout(()=>{f.style.opacity='0';setTimeout(()=>{f.style.background='rgba(255,0,0,.25)';},220);},120);
